'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare, parse } = require('./src/semver');

// 1. Numeric ordering, not lexicographic
assert.deepEqual(
  resolve({ widget: { '1.9.0': {}, '1.10.0': {}, '1.2.3': {} } }, { widget: '^1.0.0' }),
  { widget: '1.10.0' });

// 2. Backtracking: highest 'a' demands a b version that does not exist,
//    so search must fall back to the lower 'a' (first-found rule).
const reg2 = {
  a: { '2.0.0': { b: '>=2.0.0' }, '1.0.0': { b: '<2.0.0' } },
  b: { '1.0.0': {}, '1.5.0': {} },
};
assert.deepEqual(resolve(reg2, { a: '*' }), { a: '1.0.0', b: '1.5.0' });

// 3. Constraint trail rollback: after backtracking 'a', stale constraints on 'b'
//    must not poison the retry. Here a@2 requires b>=5 (unsat), a@1 requires b>=1.
const reg3 = {
  a: { '2.0.0': { b: '>=5.0.0' }, '1.0.0': { b: '>=1.0.0' } },
  b: { '1.0.0': {}, '2.0.0': {} },
};
assert.deepEqual(resolve(reg3, { a: '*' }), { a: '1.0.0', b: '2.0.0' });

// 4. Cycles terminate
const reg4 = {
  a: { '1.0.0': { b: '^1.0.0' } },
  b: { '1.0.0': { a: '^1.0.0' }, '1.1.0': { a: '^1.0.0' } },
};
assert.deepEqual(resolve(reg4, { a: '*' }), { a: '1.0.0', b: '1.1.0' });

// 5. Self-cycle with conflicting range forces backtrack
const reg5 = { a: { '2.0.0': { a: '>=2.0.0' }, '1.0.0': {} } };
assert.deepEqual(resolve(reg5, { a: '*' }), { a: '2.0.0' });
const reg5b = { a: { '2.0.0': { a: '>=3.0.0' }, '1.0.0': {} } };
assert.deepEqual(resolve(reg5b, { a: '*' }), { a: '1.0.0' });

// 6. Long dependency chain (100k) — no call-stack recursion, no iteration cap
{
  const reg = {};
  const N = 100000;
  for (let i = 0; i < N; i += 1) {
    reg['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
  }
  const out = resolve(reg, { p0: '^1.0.0' });
  assert.equal(Object.keys(out).length, N);
  assert.equal(out['p' + (N - 1)], '1.0.0');
}

// 7. Long chain with late conflict requiring deep backtrack (would exceed old 4096 cap)
{
  const reg = {};
  const N = 20000;
  for (let i = 0; i < N; i += 1) {
    reg['q' + i] = { '1.0.0': { ['q' + (i + 1)]: '^1.0.0' } };
  }
  reg['q' + N] = { '1.0.0': {}, '1.1.0': {} };
  const out = resolve(reg, { q0: '^1.0.0' });
  assert.equal(out['q' + N], '1.1.0');
}

// 8. Missing package is unsatisfiable, not malformed
assert.equal(resolve({}, { ghost: '^1.0.0' }), null);

// 9. Genuinely unsatisfiable
assert.equal(resolve({ a: { '1.0.0': {} } }, { a: '^2.0.0' }), null);

// 10. Empty root returns {}
assert.deepEqual(resolve({ a: { '1.0.0': {} } }, {}), {});

// 11. Eager validation of unreachable entries
assert.throws(() => resolve({ a: { 'not-a-version': {} } }, {}), TypeError);
assert.throws(() => resolve({ a: { '1.0.0': { b: '>>1' } } }, {}), TypeError);
assert.throws(() => resolve({ a: { '1.0.0': [] } }, {}), TypeError);
assert.throws(() => resolve([], {}), TypeError);

// 12. Null-prototype maps accepted; inputs not mutated
{
  const root = Object.create(null); root.a = '^1.0.0';
  const versions = Object.create(null); versions['1.0.0'] = Object.create(null);
  const registry = Object.create(null); registry.a = versions;
  assert.deepEqual(resolve(registry, root), { a: '1.0.0' });
  assert.deepEqual(Object.keys(registry), ['a']);
}

// 13. First-found order: FIFO discovery, highest-first per name
{
  const reg = {
    x: { '1.0.0': { z: '*' }, '2.0.0': { z: '<1.0.0' } },
    y: { '1.0.0': {} },
    z: { '0.5.0': {}, '1.0.0': {} },
  };
  // root order x then y: x@2.0.0 picked first (highest), constrains z<1.0.0
  assert.deepEqual(resolve(reg, { x: '*', y: '*' }), { x: '2.0.0', y: '1.0.0', z: '0.5.0' });
}

// 14. Caret zero-major rules
assert.equal(satisfies('0.1.5', '^0.1.2'), true);
assert.equal(satisfies('0.2.0', '^0.1.2'), false);
assert.equal(satisfies('0.0.9', '^0.0.3'), true);
assert.equal(satisfies('0.1.0', '^0.0.3'), false);
assert.equal(satisfies('1.9.9', '^1.2.3'), true);
assert.equal(satisfies('2.0.0', '^1.2.3'), false);
assert.equal(satisfies('1.5.0', '~1.2.3'), false);
assert.equal(satisfies('1.2.9', '~1.2.3'), true);
assert.equal(satisfies('1.10.0', '>=1.2.0 <2.0.0'), true);
assert.throws(() => satisfies('1.0', '^1.0.0'), TypeError);
assert.throws(() => satisfies('1.0.0', ''), TypeError);
assert.equal(compare('1.10.0', '1.9.0'), 1);
assert.deepEqual(parse('0.0.0'), [0, 0, 0]);
assert.throws(() => parse('01.0.0'), TypeError);

// 15. Cartesian-product guard: constraints prune before enumerating everything.
// 60 packages x 3 versions each; only the LAST name constrains back to the first.
// A product-enumerator would need 3^60 steps; constraint-directed search is instant.
{
  const reg = {};
  const M = 60;
  for (let i = 0; i < M; i += 1) {
    reg['r' + i] = {
      '1.0.0': i + 1 < M ? { ['r' + (i + 1)]: '*' } : { r0: '1.0.0' },
      '2.0.0': i + 1 < M ? { ['r' + (i + 1)]: '*' } : { r0: '2.0.0' },
      '3.0.0': i + 1 < M ? { ['r' + (i + 1)]: '*' } : { r0: '3.0.0' },
    };
  }
  const t0 = Date.now();
  const out = resolve(reg, { r0: '*' });
  assert.equal(out.r0, '3.0.0');
  assert.ok(Date.now() - t0 < 5000, 'took too long: product enumeration suspected');
}

// 16. Diamond: shared dep constrained by two parents
{
  const reg = {
    top: { '1.0.0': { left: '*', right: '*' } },
    left: { '1.0.0': { shared: '>=1.0.0' } },
    right: { '1.0.0': { shared: '<=1.5.0' } },
    shared: { '1.0.0': {}, '1.5.0': {}, '2.0.0': {} },
  };
  assert.deepEqual(resolve(reg, { top: '*' }),
    { top: '1.0.0', left: '1.0.0', right: '1.0.0', shared: '1.5.0' });
}

console.log('all ad-hoc checks passed');

